('home_about', 'Home About Us Section', true, $$
{
  "heading":"Kenya's most trusted moving solution",
  "lead":"Moving shouldn't be a hassle. We specialize in turning complex, stressful relocations across Kenya into smooth, blissful transitions for families and businesses alike.",
  "body":"Whether you are shifting to a new apartment or relocating an entire corporate office, our highly skilled crews arrive on time with the right equipment. We use premium packing materials to protect your valuables, ensuring that every transition is smooth, safe, and stress-free. As our promise goes: We settle you in.",
  "aboutLabel":"About Us","aboutHref":"/about","contactLabel":"Contact Our Team","contactHref":"/contact",
