('home_why_choose_us', 'Why Choose Us', true, $$
{"eyebrow":"Why Choose Shalom","heading":"We don't just move your things — we settle you in.","body":"From careful packing to secure transport, our team handles every detail so your move feels effortless. We combine years of experience with a personal touch, treating your belongings like our own and tailoring each relocation to your timeline and budget.","images":["/images/who-we-are/box-top.png","/images/who-we-are/box-bag.png","/images/who-we-are/box-bottom.png"]}
