('home_testimonials', 'Home Testimonials & Stats', true, $$
{
  "heading":"What do people have to say about us?","intro":"Real experiences from customers we've helped settle in across Kenya.",
  "stats":[{"value":"500+","label":"Happy Clients","detail":"Successfully relocated homes and offices across the country.","isVisible":true},{"value":"4.9","label":"Average Rating","detail":"Consistently rated 5-stars for our care and reliability.","isVisible":true},{"value":"24/7","label":"Support","detail":"Our dedicated team is always ready to assist you.","isVisible":true}],
  "items":[{"name":"Aisha W.","location":"Kisumu","text":"From packing to transport, they were exceptional. Affordable rates and excellent service. Will definitely use them again.","isVisible":true},{"name":"Brian K.","location":"Nairobi CBD","text":"Relocating our entire corporate office seemed impossible, but Shalom Logistics handled it flawlessly over a single weekend. Highly recommended.","isVisible":true},{"name":"Sarah M.","location":"Mombasa","text":"I was worried about my fragile items making the long trip from Nairobi to the coast. Everything arrived in pristine condition.","isVisible":true},{"name":"David O.","location":"Westlands","text":"The team showed up right on time, packed everything securely, and unpacked it just as fast. True professionals.","isVisible":true},{"name":"Grace N.","location":"Karen","text":"I loved the 'We settle you in' promise—they actually helped arrange the heavy furniture in my new living room before leaving!","isVisible":true},{"name":"Emmanuel T.","location":"Kilimani","text":"Absolutely zero stress. The crew was polite, energetic, and treated my belongings with the utmost care.","isVisible":true}]
}
$$::jsonb),
('home_faq', 'Frequently Asked Questions', true, $$
{
  "eyebrow":"Need to know","heading":"Frequently Asked Questions","intro":"Everything you need to know about moving with Shalom. If you still have questions, our team is ready to help.",
  "items":[{"question":"What areas do you cover?","answer":"We serve Nairobi and provide moving services across all major towns in Kenya. Whether you're moving within the city or relocating to another county, we've got you covered.","isVisible":true},{"question":"How much does moving cost?","answer":"Costs depend on the volume of goods, distance, and any additional services like packing or storage. Contact us for a free, no-obligation quote tailored to your needs.","isVisible":true},{"question":"Do you provide packing services?","answer":"Yes! Our professional team can handle all packing using high-quality materials to ensure your belongings arrive safely. We also offer partial packing if you'd prefer to pack some items yourself.","isVisible":true},{"question":"How far in advance should I book?","answer":"We recommend booking at least 1–2 weeks in advance, especially during peak moving seasons. However, we always try to accommodate last-minute requests whenever possible.","isVisible":true},{"question":"Is my property insured during the move?","answer":"Absolutely. We offer insurance coverage for your belongings during transit. Our team takes every precaution, but insurance gives you added peace of mind.","isVisible":true},{"question":"Do you offer storage solutions?","answer":"Yes, we provide secure short-term and long-term storage options if your new location isn't ready yet. Your items are stored in a clean, monitored facility.","isVisible":true}]
}
